2. Create /Users/shivshankardash/warden/tests/selfplay.test.ts with JSDoc file header. Tests PURE LOGIC ONLY — no network, no LLM calls, no real DB. Import from redteam/attacker.ts and redteam/defender.ts.

Test groups:

describe('isBypass', () => {
  test('ALLOW is a bypass') — isBypass('ALLOW') === true
  test('SPOTLIGHT is a bypass') — isBypass('SPOTLIGHT') === true
  test('BLOCK is not a bypass') — isBypass('BLOCK') === false
  test('QUARANTINE is not a bypass') — isBypass('QUARANTINE') === false
  test('HUMAN_REVIEW is not a bypass') — isBypass('HUMAN_REVIEW') === false
  test('SANITIZE is not a bypass') — isBypass('SANITIZE') === false
})

describe('selectWeakestTypes', () => {
  test('returns top N weakest from sorted gaps') — given gaps with detection rates [0, 0.3, 0.5, 0.8, 1.0], selectWeakestTypes(gaps, 3) returns first 3 attackTypes.
  test('returns all 9 attack types as fallback when gaps is empty') — selectWeakestTypes([]) returns array of length 9 containing all AttackType values.
  test('returns all gaps when fewer than topN') — given 2 gaps and topN=5, returns both.
  test('defaults topN to 5') — given 7 gaps, selectWeakestTypes(gaps) returns 5.
})

describe('formatBypassRecord', () => {
  test('assembles record with correct fields') — given a GeneratedAttack and scan result, verify all fields are present and correct: round, content, source, attackTypes (deduped from findings), generationContext, scanResult fields.
  test('deduplicates attackTypes from findings') — given findings with duplicate attackTypes, verify only unique types appear.
  test('handles empty findings') — attackTypes should be [] when scanResult has no findings.
  test('sets timestamp to a recent value') — timestamp should be within last 1000ms.
})

describe('formatRuleSuggestion', () => {
  test('assembles rule suggestion with bypass content') — verify bypassContent, pattern, attackType, confidence, reason, round, timestamp are set correctly.
})

describe('formatTrainingExample', () => {
  test('label is always INJECT') — formatTrainingExample(bypass).label === 'INJECT'
  test('attackType comes from generationContext.targetWeakness') — verify.
  test('source is selfplay_defender') — formatTrainingExample(bypass).source === 'selfplay_defender'
})

describe('bypass JSONL format', () => {
  test('BypassRecord serializes to valid JSON line') — JSON.stringify(formatBypassRecord(...)) should parse back correctly and contain all expected keys.
  test('RuleSuggestion serializes to valid JSON line') — same for formatRuleSuggestion.
  test('TrainingExample serializes to valid JSON line') — same for formatTrainingExample.
})

